namespace Axiom.Gameplay;
internal static class ShapeCasts {
 private static Vector3 ClosestBox(Vector3 point,Vector3 center,Vector3 half,Quaternion rotation,int dimension){var p=Quaternion.Inverse(rotation)*(point-center);return center+rotation*new Vector3(Math.Clamp(p.X,-half.X,half.X),Math.Clamp(p.Y,-half.Y,half.Y),dimension==2?0:Math.Clamp(p.Z,-half.Z,half.Z));}
 // Conservative advancement against exact closest points; bounded to 128 iterations.
 private static bool SweepSphere(Vector3 origin,double radius,Vector3 direction,double max,Func<Vector3,Vector3> closest,out double distance,out Vector3 normal){distance=0;normal=-direction;for(var i=0;i<128;i++){var p=origin+direction*distance;var q=closest(p);var delta=p-q;var gap=delta.magnitude-radius;if(gap<=1e-7){normal=delta.sqrMagnitude>1e-20?delta.normalized:-direction;return true;}var closing=-Vector3.Dot(delta.normalized,direction);if(closing<=1e-12)return false;distance+=gap/closing;if(distance>max+1e-7)return false;}return false;}
 internal static RaycastHit[] Sphere(Vector3 origin,double radius,Vector3 direction,double max,int mask,int dimension,bool triggers){PhysicsData.Finite(origin);PhysicsData.Finite(direction);max=PhysicsQueries.Distance(max);if(!double.IsFinite(radius)||radius<0)throw new ArgumentException("Invalid cast radius");if(dimension==2)direction.Z=0;if(direction.sqrMagnitude<1e-24)return Array.Empty<RaycastHit>();direction=direction.normalized;var hits=new List<RaycastHit>();foreach(var c in PhysicsQueries.Candidates(dimension,mask,triggers)){var center=origin;if(dimension==2)center.Z=c.transform.position.Z;if(SweepSphere(center,radius,direction,max,p=>PhysicsQueries.Closest(c,p),out var distance,out var normal))hits.Add(new(c,distance,center+direction*distance-normal*radius,normal));}return hits.OrderBy(h=>h.distance).ThenBy(h=>h.collider.Entity.Id,StringComparer.Ordinal).ToArray();}
 internal static RaycastHit[] Box(Vector3 origin,Vector3 half,Vector3 direction,Quaternion rotation,double max,int mask,int dimension,bool triggers){PhysicsData.Finite(origin);PhysicsData.Finite(half);PhysicsData.Finite(direction);max=PhysicsQueries.Distance(max);var norm=rotation.X*rotation.X+rotation.Y*rotation.Y+rotation.Z*rotation.Z+rotation.W*rotation.W;if(half.X<0||half.Y<0||half.Z<0||!double.IsFinite(norm)||norm<1e-12)throw new ArgumentException("Invalid cast box");rotation=new(rotation.X/Math.Sqrt(norm),rotation.Y/Math.Sqrt(norm),rotation.Z/Math.Sqrt(norm),rotation.W/Math.Sqrt(norm));if(dimension==2)direction.Z=0;if(direction.sqrMagnitude<1e-24)return Array.Empty<RaycastHit>();direction=direction.normalized;var hits=new List<RaycastHit>();var aa=new[]{rotation*Vector3.right,rotation*Vector3.up,rotation*Vector3.forward};var h=new[]{half.X,half.Y,half.Z};foreach(var c in PhysicsQueries.Candidates(dimension,mask,triggers)){var t=c.Entity.Transform;var ch=PhysicsData.Half(c.Entity);var center=origin;if(dimension==2)center.Z=t.Position.Z;double enter=0;var normal=-direction;bool hit=true;if(c.Data.GetProperty("shape").GetString()=="sphere"){hit=SweepSphere(t.Position,ch.X,-direction,max,p=>ClosestBox(p,center,half,rotation,dimension),out enter,out var inverse);normal=-inverse;}else {var ba=new[]{t.Rotation*Vector3.right,t.Rotation*Vector3.up,t.Rotation*Vector3.forward};var k=new[]{ch.X,ch.Y,ch.Z};var axes=new List<Vector3>();axes.AddRange(aa.Take(dimension));axes.AddRange(ba.Take(dimension));if(dimension==3)foreach(var a in aa)foreach(var b in ba){var n=Vector3.Cross(a,b);if(n.sqrMagnitude>1e-12)axes.Add(n.normalized);}double exit=max;foreach(var n in axes){double r=0;for(var i=0;i<dimension;i++)r+=h[i]*Math.Abs(Vector3.Dot(aa[i],n))+k[i]*Math.Abs(Vector3.Dot(ba[i],n));var offset=Vector3.Dot(t.Position-center,n);var speed=Vector3.Dot(direction,n);if(Math.Abs(speed)<1e-12){if(Math.Abs(offset)>r){hit=false;break;}continue;}var start=(offset-r)/speed;var end=(offset+r)/speed;if(start>end)(start,end)=(end,start);if(start>enter){enter=start;normal=n*(speed>0?-1:1);}exit=Math.Min(exit,end);if(enter>exit){hit=false;break;}}}if(hit&&enter>=0&&enter<=max){var p=center+direction*enter;var contact=PhysicsQueries.Closest(c,ClosestBox(t.Position,p,half,rotation,dimension));hits.Add(new(c,enter,contact,normal));}}return hits.OrderBy(h=>h.distance).ThenBy(h=>h.collider.Entity.Id,StringComparer.Ordinal).ToArray();}
}
public static partial class Physics {
 public static RaycastHit[] SphereCastAll(Vector3 origin,double radius,Vector3 direction,double maxDistance=double.PositiveInfinity,int layerMask=DefaultRaycastLayers,QueryTriggerInteraction queryTriggerInteraction=QueryTriggerInteraction.UseGlobal)=>ShapeCasts.Sphere(origin,radius,direction,maxDistance,layerMask,3,PhysicsQueries.Triggers(queryTriggerInteraction));
 public static bool SphereCast(Vector3 origin,double radius,Vector3 direction,out RaycastHit hit,double maxDistance=double.PositiveInfinity,int layerMask=DefaultRaycastLayers,QueryTriggerInteraction queryTriggerInteraction=QueryTriggerInteraction.UseGlobal){var hits=SphereCastAll(origin,radius,direction,maxDistance,layerMask,queryTriggerInteraction);hit=hits.FirstOrDefault();return hits.Length>0;}
 public static int SphereCastNonAlloc(Vector3 origin,double radius,Vector3 direction,RaycastHit[] results,double maxDistance=double.PositiveInfinity,int layerMask=DefaultRaycastLayers,QueryTriggerInteraction queryTriggerInteraction=QueryTriggerInteraction.UseGlobal)=>PhysicsQueries.Fill(SphereCastAll(origin,radius,direction,maxDistance,layerMask,queryTriggerInteraction),results);
 public static RaycastHit[] BoxCastAll(Vector3 center,Vector3 halfExtents,Vector3 direction,Quaternion orientation,double maxDistance=double.PositiveInfinity,int layerMask=DefaultRaycastLayers,QueryTriggerInteraction queryTriggerInteraction=QueryTriggerInteraction.UseGlobal)=>ShapeCasts.Box(center,halfExtents,direction,orientation,maxDistance,layerMask,3,PhysicsQueries.Triggers(queryTriggerInteraction));
 public static bool BoxCast(Vector3 center,Vector3 halfExtents,Vector3 direction,out RaycastHit hit,Quaternion orientation,double maxDistance=double.PositiveInfinity,int layerMask=DefaultRaycastLayers,QueryTriggerInteraction queryTriggerInteraction=QueryTriggerInteraction.UseGlobal){var hits=BoxCastAll(center,halfExtents,direction,orientation,maxDistance,layerMask,queryTriggerInteraction);hit=hits.FirstOrDefault();return hits.Length>0;}
 public static int BoxCastNonAlloc(Vector3 center,Vector3 halfExtents,Vector3 direction,RaycastHit[] results,Quaternion orientation,double maxDistance=double.PositiveInfinity,int layerMask=DefaultRaycastLayers,QueryTriggerInteraction queryTriggerInteraction=QueryTriggerInteraction.UseGlobal)=>PhysicsQueries.Fill(BoxCastAll(center,halfExtents,direction,orientation,maxDistance,layerMask,queryTriggerInteraction),results);
}
public static partial class Physics2D {
 public static RaycastHit2D[] CircleCastAll(Vector2 origin,double radius,Vector2 direction,double distance=double.PositiveInfinity,int layerMask=DefaultRaycastLayers)=>ShapeCasts.Sphere(new(origin.X,origin.Y,0),radius,new(direction.X,direction.Y,0),distance,layerMask,2,queriesHitTriggers).Select(PhysicsQueries.Hit2D).ToArray();
 public static RaycastHit2D CircleCast(Vector2 origin,double radius,Vector2 direction,double distance=double.PositiveInfinity,int layerMask=DefaultRaycastLayers)=>CircleCastAll(origin,radius,direction,distance,layerMask).FirstOrDefault();
 public static int CircleCastNonAlloc(Vector2 origin,double radius,Vector2 direction,RaycastHit2D[] results,double distance=double.PositiveInfinity,int layerMask=DefaultRaycastLayers)=>PhysicsQueries.Fill(CircleCastAll(origin,radius,direction,distance,layerMask),results);
 public static RaycastHit2D[] BoxCastAll(Vector2 origin,Vector2 size,double angle,Vector2 direction,double distance=double.PositiveInfinity,int layerMask=DefaultRaycastLayers)=>ShapeCasts.Box(new(origin.X,origin.Y,0),new(size.X/2,size.Y/2,0),new(direction.X,direction.Y,0),Quaternion.Euler(0,0,angle),distance,layerMask,2,queriesHitTriggers).Select(PhysicsQueries.Hit2D).ToArray();
 public static RaycastHit2D BoxCast(Vector2 origin,Vector2 size,double angle,Vector2 direction,double distance=double.PositiveInfinity,int layerMask=DefaultRaycastLayers)=>BoxCastAll(origin,size,angle,direction,distance,layerMask).FirstOrDefault();
 public static int BoxCastNonAlloc(Vector2 origin,Vector2 size,double angle,Vector2 direction,RaycastHit2D[] results,double distance=double.PositiveInfinity,int layerMask=DefaultRaycastLayers)=>PhysicsQueries.Fill(BoxCastAll(origin,size,angle,direction,distance,layerMask),results);
}
